/// Intersection of the state machine, the caller relation and permission keys. The UI hides what is absent and never re-derives it.
enum RequestAction {
  withdraw('withdraw'),
  cancel('cancel'),
  confirm('confirm'),
  acceptProposal('accept_proposal'),
  declineProposal('decline_proposal'),
  message('message'),
  call('call'),
  visit('visit'),
  review('review'),
  reportIssue('report_issue'),
  redeem('redeem'),
  accept('accept'),
  decline('decline'),
  propose('propose'),
  revoke('revoke'),
  openVoucher('open_voucher'),
  unknown('unknown');

  const RequestAction(this.value);

  /// The wire value.
  final String value;

  /// Unknown values never crash a client: they read as [unknown] (api-conventions section 2).
  static RequestAction fromJson(Object? v) {
    for (final e in values) {
      if (e.value == v) return e;
    }
    return RequestAction.unknown;
  }

  String toJson() => value;
}

