/// R01. Sends the request at the voucher price and binds the voucher. Validated server side; the quote is re-priced and compared with `quoteId`.
final class CreateRequestInput {
  const CreateRequestInput({
    required this.targetType,
    this.venueId,
    this.providerId,
    required this.eventDate,
    this.sections,
    this.service,
    this.extras,
    required this.voucherId,
    this.quoteId,
    required this.contact,
    this.specialRequests,
  });

  factory CreateRequestInput.fromJson(Map<String, Object?> json) {
    try {
      return CreateRequestInput(
        targetType: reqField(json, 'targetType', (v) => BookingTargetType.fromJson(v)),
        venueId: optField(json, 'venueId', (v) => asString(v)),
        providerId: optField(json, 'providerId', (v) => asString(v)),
        eventDate: reqField(json, 'eventDate', (v) => asLocalDate(v)),
        sections: optField(json, 'sections', (v) => asList(v, (v1) => RequestSectionInput.fromJson(asMap(v1)))),
        service: optField(json, 'service', (v) => RequestServiceInput.fromJson(asMap(v))),
        extras: optField(json, 'extras', (v) => asList(v, (v1) => QuoteExtraInput.fromJson(asMap(v1)))),
        voucherId: reqField(json, 'voucherId', (v) => asString(v)),
        quoteId: optField(json, 'quoteId', (v) => asString(v)),
        contact: reqField(json, 'contact', (v) => ContactInput.fromJson(asMap(v))),
        specialRequests: optField(json, 'specialRequests', (v) => asString(v)),
      );
    } on FormatException catch (e) {
      throw FormatException('CreateRequestInput: ${e.message}');
    }
  }

  final BookingTargetType targetType;
  final String? venueId;
  final String? providerId;
  final LocalDate eventDate;
  final List<RequestSectionInput>? sections;
  final RequestServiceInput? service;
  final List<QuoteExtraInput>? extras;
  final String voucherId;
  final String? quoteId;
  final ContactInput contact;
  final String? specialRequests;

  Map<String, Object?> toJson() => {
      'targetType': targetType.toJson(),
      if (venueId != null) 'venueId': venueId!,
      if (providerId != null) 'providerId': providerId!,
      'eventDate': eventDate.toJson(),
      if (sections != null) 'sections': sections!.map((v1) => v1.toJson()).toList(),
      if (service != null) 'service': service!.toJson(),
      if (extras != null) 'extras': extras!.map((v1) => v1.toJson()).toList(),
      'voucherId': voucherId,
      if (quoteId != null) 'quoteId': quoteId!,
      'contact': contact.toJson(),
      if (specialRequests != null) 'specialRequests': specialRequests!,
      };

  CreateRequestInput copyWith({
    BookingTargetType? targetType,
    Object? venueId = unsetValue,
    Object? providerId = unsetValue,
    LocalDate? eventDate,
    Object? sections = unsetValue,
    Object? service = unsetValue,
    Object? extras = unsetValue,
    String? voucherId,
    Object? quoteId = unsetValue,
    ContactInput? contact,
    Object? specialRequests = unsetValue,
  }) => CreateRequestInput(
      targetType: targetType ?? this.targetType,
      venueId: identical(venueId, unsetValue) ? this.venueId : venueId as String?,
      providerId: identical(providerId, unsetValue) ? this.providerId : providerId as String?,
      eventDate: eventDate ?? this.eventDate,
      sections: identical(sections, unsetValue) ? this.sections : sections as List<RequestSectionInput>?,
      service: identical(service, unsetValue) ? this.service : service as RequestServiceInput?,
      extras: identical(extras, unsetValue) ? this.extras : extras as List<QuoteExtraInput>?,
      voucherId: voucherId ?? this.voucherId,
      quoteId: identical(quoteId, unsetValue) ? this.quoteId : quoteId as String?,
      contact: contact ?? this.contact,
      specialRequests: identical(specialRequests, unsetValue) ? this.specialRequests : specialRequests as String?,
      );

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is CreateRequestInput &&
          other.targetType == targetType &&
          other.venueId == venueId &&
          other.providerId == providerId &&
          other.eventDate == eventDate &&
          deepEquals(other.sections, sections) &&
          other.service == service &&
          deepEquals(other.extras, extras) &&
          other.voucherId == voucherId &&
          other.quoteId == quoteId &&
          other.contact == contact &&
          other.specialRequests == specialRequests;

  @override
  int get hashCode => Object.hashAll([targetType, venueId, providerId, eventDate, deepHash(sections), service, deepHash(extras), voucherId, quoteId, contact, specialRequests]);

  @override
  String toString() => 'CreateRequestInput(${toJson()})';
}

